760	    /// `foo::Engine::start()` does NOT also resolve `bar::Engine::start()` (same
761	    /// bare owner key, different module) as Exact. Narrowing only applies when
762	    /// module segments are present AND there is >1 candidate; if it eliminates
763	    /// everything it is ignored (a wrong module hint must not drop a real edge).
764	    fn owner_lookup_in_modules(
765	        &self,
766	        owner: &str,
767	        name: &str,
768	        module_segs: &[&str],
769	    ) -> Option<Vec<ResolvedCallee<'_>>> {
770	        let ids = self.methods.get(&(owner.to_string(), name.to_string()))?;
771	        let pool: Vec<&FunctionId> = if !module_segs.is_empty() && ids.len() > 1 {
772	            let narrowed: Vec<&FunctionId> = ids
773	                .iter()
774	                .filter(|fid| {
775	                    module_segs
776	                        .iter()
777	                        .any(|seg| file_has_path_segment(&fid.file, seg))
778	                })
779	                .collect();
780	            if narrowed.is_empty() {
781	                ids.iter().collect()
782	            } else {
783	                narrowed
784	            }
785	        } else {
786	            ids.iter().collect()
787	        };
788	        let primary_owners: BTreeSet<&str> = pool
789	            .iter()
790	            .filter_map(|fid| self.method_owners.get(*fid).map(|s| s.as_str()))
791	            .collect();
792	        Some(if pool.len() > 1 && primary_owners.len() > 1 {
793	            // Multiple DISTINCT primary owners — trait-CHA (dyn Trait). Unchanged.
794	            demoted(pool, ResolutionKind::TraitCha)
795	        } else if pool.len() > 1 {
796	            // Non-trait multi-candidate owner-key ambiguity: >1 candidate under one
797	            // primary owner name with no scope proof reached here — same-name-type
798	            // collisions, overloads, or inherent+trait same-name dups. Demote: keep
799	            // every edge (recall) but not at full confidence. Kind stays
800	            // QualifiedOwner so caller relabels (R3b/Self::/R6/implicit-this) fire
801	            // unchanged; only the confidence rides through as NameOnly. Recoverable
802	            // to Exact once an upstream capability supplies the discrimination.
803	            demoted(pool, ResolutionKind::QualifiedOwner)
804	        } else {
805	            // Single candidate — Exact, unchanged.
