fn test_python_r3b_collision_and_local_miss_fallthrough() {
    let collision = graph(&[(
        "svc.py",
        "class x:\n    def m(self):\n        pass\nclass Foo:\n    def m(self):\n        pass\ndef run(x: Foo):\n    x.m()\n",
    )]);
